import pickle, numpy as np
with open('/app/converted_data.pkl','rb') as f:d=pickle.load(f)
ops={
'identity':lambda a:a,
'rot90':lambda a:np.rot90(a,1),
'rot180':lambda a:np.rot90(a,2),
'rot270':lambda a:np.rot90(a,3),
'transpose':lambda a:a.T,
'flipud':lambda a:np.flipud(a),
'fliplr':lambda a:np.fliplr(a),
'antitranspose':lambda a:np.rot90(a.T,2),
}
counts={k:0 for k in ops}; total=0; accessible={k:0 for k in ops}
for inp,outs in zip(d['input'],d['output']):
 labels=np.concatenate([x[0] for x in outs]); total+=len(labels)
 raw=inp[0].reshape(3,3)
 for k,fn in ops.items(): counts[k]+=int(fn(raw).ravel()[labels].sum())
print('total',total)
for k,v in counts.items():print(k,v,v/total)
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":10000});
